CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(150) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE);
CREATE TABLE books (id BIGSERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, author VARCHAR(200) NOT NULL, price NUMERIC(12,2) NOT NULL CHECK (price >= 0), stock INT NOT NULL DEFAULT 0 CHECK (stock >= 0), category_id BIGINT REFERENCES categories(id));
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, customer_name VARCHAR(150) NOT NULL, customer_email VARCHAR(255) NOT NULL, total_amount NUMERIC(12,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, book_id BIGINT NOT NULL REFERENCES books(id), quantity INT NOT NULL CHECK (quantity > 0), unit_price NUMERIC(12,2) NOT NULL);
